1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strings"
10	
11		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
12	)
13	
14	// replicateInput 是 replicate 子命令从标准输入读取的 JSON。
15	//
16	// log、requests 以及请求内 entries 是允许在同一对象中重复出现的数组字段，约定
17	// 后者生效。encoding/json 把重复出现的数组解到同一个非 nil 切片时，只会按下标
18	// 覆盖既有元素：后一份数组较短时尾部残留旧元素，元素省略的字段（command、
19	// index、term）也会从相同位置的旧元素继承，等于让用户给出的后一份日志借用了
20	// 前一份的内容。因此这三个数组都用整体替换的包装类型（replicateInputLog 等）
21	// 解码：每一次出现都解进一份全新的切片并整体替换，最后一份数组是什么就保留
22	// 什么，元素省略的数值按默认 0、省略的命令按空字符串解释。
23	type replicateInput struct {
24		CurrentTerm    int                    `json:"currentTerm"`
25		CommittedIndex int                    `json:"committedIndex"`
26		Log            replicateInputLog      `json:"log"`
27		ApplyKV        bool                   `json:"applyKV"`
28		Requests       replicateInputRequests `json:"requests"`
29	}
30	
31	// replicateInputLog 是根对象的 log 字段：重复出现时最后一份数组整体替换。
32	type replicateInputLog []mevwatch.LogEntry
33	
34	func (l *replicateInputLog) UnmarshalJSON(data []byte) error {
35		return unmarshalLastWinsArray(data, (*[]mevwatch.LogEntry)(l))
36	}
37	
38	// replicateInputRequest 与 mevwatch.AppendRequest 字段相同，区别只是 entries
39	// 也走整体替换解码。
40	type replicateInputRequest struct {
41		Term         int                   `json:"term"`
42		PrevLogIndex int                   `json:"prevLogIndex"`
43		PrevLogTerm  int                   `json:"prevLogTerm"`
44		Entries      replicateInputEntries `json:"entries"`
45		LeaderCommit int                   `json:"leaderCommit"`
46	}
47	
48	// replicateInputRequests 是根对象的 requests 字段：重复出现时最后一份数组
49	// 整体替换，而不是把后一份请求按下标并进前一份。
50	type replicateInputRequests []replicateInputRequest
51	
52	func (r *replicateInputRequests) UnmarshalJSON(data []byte) error {
53		return unmarshalLastWinsArray(data, (*[]replicateInputRequest)(r))
54	}
55	
56	// replicateInputEntries 是单个请求内的 entries 字段：同一请求对象里重复
57	// 出现时，最后一份条目数组整体替换。
58	type replicateInputEntries []mevwatch.LogEntry
59	
60	func (e *replicateInputEntries) UnmarshalJSON(data []byte) error {
61		return unmarshalLastWinsArray(data, (*[]mevwatch.LogEntry)(e))
62	}
63	
64	// unmarshalLastWinsArray 把一次数组字段出现解进一份全新的切片，并用它整体
65	// 替换 dst。它必须先解进局部切片而不能直接解到 dst：encoding/json 对“非 nil
66	// 现有切片 + 重复数组键”只做下标覆盖，短数组的尾部与元素内省略的字段都会
67	// 残留上一次出现的内容。null 与既有行为一致，把目标置为空切片（nil）。
68	func unmarshalLastWinsArray[T any](data []byte, dst *[]T) error {
69		var next []T
70		if err := json.Unmarshal(data, &next); err != nil {
71			return err
72		}
73		*dst = next
74		return nil
75	}
76	
77	// runReplicate 从标准输入读取一份 JSON（初始状态 + 顺序到达的复制请求），
78	// 把逐次接收结果与最终日志作为一份 JSON 写到标准输出。
79	// 初始状态非法或 JSON 无法解析时，以非零退出码和明确错误结束。
80	func runReplicate() int {
81		return runReplicateIO(os.Stdin, os.Stdout, os.Stderr)
82	}
83	
84	func runReplicateIO(stdin io.Reader, stdout, stderr io.Writer) int {
85		data, err := io.ReadAll(stdin)
86		if err != nil {
87			fmt.Fprintf(stderr, "replicate: read stdin: %v\n", err)
88			return 1
89		}
90		// 语法检查用 UseNumber 流式解码而不是解进 interface{}：后者把每个数字
91		// 都转成 float64，未知字段里 1e400 这类超出浮点范围但完全合法的 JSON
92		// 数字会让整份输入在解析阶段被误判为输入错误。未知字段不参与跟随者
93		// 状态计算，其数值大小不应决定输入能否解析；UseNumber 把数字保留为
94		// 原始字面量，只校验语法不做范围转换。已识别数值字段上的同类大数仍由
95		// 随后的类型化解码按既有整数范围限制拒绝。
96		syntaxDec := json.NewDecoder(bytes.NewReader(data))
97		syntaxDec.UseNumber()
98		var syntaxCheck interface{}
99		if err := syntaxDec.Decode(&syntaxCheck); err != nil {
100			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
101			return 1
102		}
103		// 与 json.Unmarshal 一致：一份完整文档之后不允许再跟另一份 JSON 或
104		// 其他内容。
105		if syntaxDec.More() {
106			fmt.Fprintf(stderr, "replicate: parse input JSON: unexpected data after top-level JSON value\n")
107			return 1
108		}
109		// 已识别的数值字段被显式写成 null 时，类型化解码会静默当成零值继续
110		// 处理（例如 committedIndex 为 null 被当成“尚未提交”），必须在读取
111		// 输入阶段把整份输入作为字段类型错误拒绝。检查直接扫描 JSON token
112		// 而不是先解进 map：map 解码对重复键只保留最后一次出现，既会漏掉
113		// 写在数字前面的 null，也会让后出现的 log/requests/entries 数组盖掉
114		// 前一份数组，因此重复键的每一次出现都必须单独检查。
115		if path := nullNumericFieldPath(data); path != "" {
116			fmt.Fprintf(stderr, "replicate: invalid field type: %s must be a number, got null\n", path)
117			return 1
118		}
119		var input replicateInput
120		if err := json.Unmarshal(data, &input); err != nil {
121			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
122			return 1
123		}
124		// 三个数组经整体替换解码后再逐元素转成库类型：转换只按最后一份数组的实际
125		// 内容进行，不携带任何同名前序数组的条目字段。
126		initialLog := append([]mevwatch.LogEntry(nil), input.Log...)
127		requests := make([]mevwatch.AppendRequest, len(input.Requests))
128		for i, req := range input.Requests {
129			requests[i] = mevwatch.AppendRequest{
130				Term:         req.Term,
131				PrevLogIndex: req.PrevLogIndex,
132				PrevLogTerm:  req.PrevLogTerm,
133				Entries:      append([]mevwatch.LogEntry(nil), req.Entries...),
134				LeaderCommit: req.LeaderCommit,
135			}
136		}
137		output, err := mevwatch.ReplicateWithOptions(mevwatch.InitialState{
138			CurrentTerm:    input.CurrentTerm,
139			CommittedIndex: input.CommittedIndex,
140			Log:            initialLog,
141		}, requests, mevwatch.ReplicateOptions{ApplyKV: input.ApplyKV})
142		if err != nil {
143			fmt.Fprintf(stderr, "replicate: %v\n", err)
144			return 1
145		}
146		encoded, err := json.MarshalIndent(output, "", "  ")
147		if err != nil {
148			fmt.Fprintf(stderr, "replicate: encode output JSON: %v\n", err)
149			return 1
150		}
151		fmt.Fprintln(stdout, string(encoded))
152		return 0
153	}
154	
155	// objectSchema 描述某一层次对象里已识别的字段：numerics 是显式写成 null 时
156	// 必须拒绝整份输入的数值字段（标准拼写），arrays 是元素为对象的数组字段及其
157	// 元素层次。字段名识别与 encoding/json 一致，只改变字母大小写的写法同样命中；
158	// 错误位置始终使用这里的标准拼写而不是输入里的大小写变体。根状态、复制请求
159	// 与日志条目共用同一套扫描逻辑，区别只在下面三份 schema。
160	type objectSchema struct {
161		numerics []string
162		arrays   []arrayField
163	}
164	
165	// arrayField 是一个已识别的对象数组字段：name 为标准字段名，elem 为数组元素
166	// 所在层次的 schema。
167	type arrayField struct {
168		name string
169		elem *objectSchema
170	}
171	
172	var (
173		// 日志条目层次：log[i] 与 requests[r].entries[i] 是同一种对象。
174		entryObjectSchema = &objectSchema{numerics: []string{"index", "term"}}
175		// 复制请求层次：数值字段外还嵌套 entries 条目数组。
176		requestObjectSchema = &objectSchema{
177			numerics: []string{"term", "prevLogIndex", "prevLogTerm", "leaderCommit"},
178			arrays:   []arrayField{{name: "entries", elem: entryObjectSchema}},
179		}
180		// 根输入层次：初始状态的数值字段外还嵌套 log 与 requests 两个数组。
181		rootObjectSchema = &objectSchema{
182			numerics: []string{"currentTerm", "committedIndex"},
183			arrays: []arrayField{
184				{name: "log", elem: entryObjectSchema},
185				{name: "requests", elem: requestObjectSchema},
186			},
187		}
188	)
189	
190	// numericName 在 key 命中本层次某个已识别数值字段时返回它的标准拼写。
191	func (s *objectSchema) numericName(key string) (string, bool) {
192		for _, name := range s.numerics {
193			if strings.EqualFold(key, name) {
194				return name, true
195			}
196		}
197		return "", false
198	}
199	
200	// arrayField 在 key 命中本层次某个已识别数组字段时返回它的定义（含标准拼写）。
201	func (s *objectSchema) arrayField(key string) (arrayField, bool) {
202		for _, field := range s.arrays {
203			if strings.EqualFold(key, field.name) {
204				return field, true
205			}
206		}
207		return arrayField{}, false
208	}
209	
210	// nullNumericFieldPath 扫描整份输入 JSON 的 token 流，查找第一个被显式写成
211	// null 的已识别数值字段，返回它的完整位置；没有时返回空串。检查范围是初始
212	// 状态（currentTerm、committedIndex、log[i].index、log[i].term）与每条复制
213	// 请求（term、prevLogIndex、prevLogTerm、leaderCommit 及 entries[j].index、
214	// entries[j].term）；请求与条目下标从 0 开始，例如第二条请求的提交位置记为
215	// requests[1].leaderCommit。
216	//
217	// 必须扫描 token 而不能先解进 map[string]interface{}：map 解码遇到重复键只
218	// 保留最后一次出现的值。{"currentTerm":null,"currentTerm":1} 里先出现的
219	// null 会因此漏检；log/requests/entries 自身重复出现时，前一份数组里的数值
220	// null 也会被后一份数组盖掉。token 流保留键的每一次出现，重复字段无论 null
221	// 在数字之前还是之后、数组字段重复多少次、拼写是否只改变大小写，都逃不过
222	// 检查。数组字段本身为 null、未知键（含未知对象里的同名键）里的 null 不在
223	// 检查范围内，扫描时只按结构识别已知字段，不进入其他对象与数组。
224	func nullNumericFieldPath(data []byte) string {
225		dec := json.NewDecoder(bytes.NewReader(data))
226		// 数字一律按原始字面量（json.Number）读取：默认的 Token 行为会把数字
227		// 转成 float64，未知字段里 1e400 这类超出浮点范围的合法数字会让扫描
228		// 中途出错返回，从而遮住排在其后的真实数值 null。这里只关心结构，
229		// 不需要任何数值转换。
230		dec.UseNumber()
231	
232		// 取根对象的第一个 token；输入不是对象或 JSON 非法时没有可报告的数值
233		// 字段位置，交由随后的类型化解码产出既有的解析错误。
234		tok, err := dec.Token()
235		if err != nil || tok != json.Delim('{') {
236			return ""
237		}
238		return scanObjectFields(dec, rootObjectSchema, "")
239	}
240	
241	// scanObjectFields 扫描一个已读入起始 '{' 的对象的字段流，prefix 是该对象
242	// 的位置前缀（根对象为空，其余层次以 "." 结尾，如 "requests[1]."）。每个键
243	// 按所在层次的 schema 分派：已识别数值字段检查是否写成 null，已识别数组字段
244	// 递归扫描元素，其余键的值整体跳过。返回第一个数值 null 的完整位置。
245	func scanObjectFields(dec *json.Decoder, schema *objectSchema, prefix string) string {
246		for dec.More() {
247			key, ok := decodeKey(dec)
248			if !ok {
249				return ""
250			}
251			if name, ok := schema.numericName(key); ok {
252				if nullScalarPath(dec) {
253					return prefix + name
254				}
255				continue
256			}
257			if field, ok := schema.arrayField(key); ok {
258				if path := scanObjectArray(dec, field.elem, prefix+field.name); path != "" {
259					return path
260				}
261				continue
262			}
263			skipValue(dec)
264		}
265		return ""
266	}
267	
268	// scanObjectArray 扫描一个对象数组字段的完整 token 流（数组字段重复出现时由
269	// 调用方对每一份数组分别调用），arrayPath 是数组自身的位置（如 "log" 或
270	// "requests[r].entries"），返回第一个数值 null 的完整位置。
271	func scanObjectArray(dec *json.Decoder, elem *objectSchema, arrayPath string) string {
272		tok, err := dec.Token()
273		if err != nil {
274			return ""
275		}
276		if tok != json.Delim('[') {
277			// 数组字段本身为 null 或其他类型（如被写成对象）：沿用既有处理，
278			// 类型错误由随后的类型化解码按既有格式报告。这里必须把整个值消费
279			// 完——起始分隔符已经读出，若就此返回，调用方的循环会落到对象内部，
280			// 把其中的 term/index 等字段当成外层已识别字段，其后的真实数值
281			// null 也会被漏检。
282			if d, ok := tok.(json.Delim); ok {
283				skipRest(dec, d)
284			}
285			return ""
286		}
287		for i := 0; dec.More(); i++ {
288			tok, err := dec.Token()
289			if err != nil {
290				return ""
291			}
292			if tok != json.Delim('{') {
293				// 非对象元素不可能含已识别字段；若它本身是容器仍要消费完整。
294				if d, ok := tok.(json.Delim); ok {
295					skipRest(dec, d)
296				}
297				continue
298			}
299			prefix := fmt.Sprintf("%s[%d].", arrayPath, i)
300			if path := scanObjectFields(dec, elem, prefix); path != "" {
301				return path
302			}
303			if _, err := dec.Token(); err != nil { // 元素对象的 '}'
304				return ""
305			}
306		}
307		if _, err := dec.Token(); err != nil { // 数组的 ']'
308			return ""
309		}
310		return ""
311	}
312	
313	// decodeKey 读取并断言下一个 token 是对象键。
314	func decodeKey(dec *json.Decoder) (string, bool) {
315		tok, err := dec.Token()
316		if err != nil {
317			return "", false
318		}
319		key, ok := tok.(string)
320		return key, ok
321	}
322	
323	// nullScalarPath 消费一个已识别数值字段的值 token 流，报告该次出现是否被
324	// 显式写成 null。值为对象或数组时整体跳过（结构异常的输入留给类型化解码
325	// 报告既有错误）。
326	func nullScalarPath(dec *json.Decoder) bool {
327		tok, err := dec.Token()
328		if err != nil {
329			return false
330		}
331		if tok == nil {
332			return true
333		}
334		if d, ok := tok.(json.Delim); ok {
335			skipRest(dec, d)
336		}
337		return false
338	}
339	
340	// skipValue 读取并消费一个完整的 JSON 值（标量或容器）。
341	func skipValue(dec *json.Decoder) {
342		tok, err := dec.Token()
343		if err != nil {
344			return
345		}
346		if d, ok := tok.(json.Delim); ok {
347			skipRest(dec, d)
348		}
349	}
350	
351	// skipRest 消费一个容器剩余的 token 流，open 是已经读出的起始分隔符；
352	// 起始分隔符不是 '{' / '[' 时无需消费，直接返回。
353	func skipRest(dec *json.Decoder, open json.Delim) {
354		if open != '{' && open != '[' {
355			return
356		}
357		depth := 1
358		for depth > 0 {
359			tok, err := dec.Token()
360			if err != nil {
361				return
362			}
363			if d, ok := tok.(json.Delim); ok {
364				switch d {
365				case '{', '[':
366					depth++
367				case '}', ']':
368					depth--
369				}
370			}
371		}
372	}
