1	package main
2	
3	import (
4		"testing"
5	
6		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
7	)
8	
9	// 重复数组整体替换回归：同一输入里 log、requests 以及同一请求对象内的
10	// entries 重复出现时，最后一份数组必须整体替换之前的数组。元素只按最后一份
11	// 的内容解释——省略的命令为空字符串、省略的数值为 0、省略的条目数组为空，
12	// 不能从相同位置的旧元素继承任期、索引、提交位置、命令或条目；数组变短时也
13	// 只保留最后一份实际给出的元素。下列用例锁定这些语义。
14	
15	// 任务主场景（关闭键值应用）：任期 1、已提交索引 1，先给一条
16	// index=term=1、command="set a=1" 的日志，再给一条同索引同任期却省略
17	// command 的日志。最终日志命令必须为空，而不是前一份的 set a=1。
18	func TestCLIDuplicateLogLaterEntryOmitsCommandLeavesEmpty(t *testing.T) {
19		input := `{"currentTerm":1,"committedIndex":1,
20		  "log":[{"index":1,"term":1,"command":"set a=1"}],
21		  "log":[{"index":1,"term":1}]}`
22		out := runReplicateJSON(t, input)
23		if len(out.FinalLog) != 1 {
24			t.Fatalf("final log has %d entries, want 1: %+v", len(out.FinalLog), out.FinalLog)
25		}
26		got := out.FinalLog[0]
27		want := mevwatch.LogEntry{Index: 1, Term: 1, Command: ""}
28		if got != want {
29			t.Fatalf("final log entry = %+v, want %+v (command must not be borrowed from the first log)", got, want)
30		}
31	}
32	
33	// 同一场景开启 applyKV：空命令按现有未知命令规则报告索引 1 的应用错误，
34	// 已应用索引停在 0，键值表为空——被替换掉的 set a=1 不能留下写入。
35	func TestCLIDuplicateLogLaterEmptyCommandApplyKVReportsError(t *testing.T) {
36		input := `{"currentTerm":1,"committedIndex":1,"applyKV":true,
37		  "log":[{"index":1,"term":1,"command":"set a=1"}],
38		  "log":[{"index":1,"term":1}]}`
39		out := runReplicateJSON(t, input)
40		if out.FinalAppliedIndex == nil || *out.FinalAppliedIndex != 0 {
41			t.Fatalf("finalAppliedIndex = %+v, want 0", out.FinalAppliedIndex)
42		}
43		if out.FinalApplyError == nil || out.FinalApplyError.Index != 1 ||
44			out.FinalApplyError.Reason != mevwatch.ApplyReasonUnknownCommand {
45			t.Fatalf("finalApplyError = %+v, want index 1 unknown command", out.FinalApplyError)
46		}
47		if len(out.FinalKV) != 0 {
48			t.Fatalf("finalKV = %v, want empty table (the replaced write must not apply)", out.FinalKV)
49		}
50	}
51	
52	// 最后一份日志的条目若省略 index 或 term，按默认 0 解释并以非法初始状态
53	// 结束，不能借先前条目的合法值通过校验。
54	func TestCLIDuplicateLogLaterEntryOmitsIndexOrTermIsInvalidInitialState(t *testing.T) {
55		cases := []struct {
56			name  string
57			entry string
58		}{
59			{name: "omits index", entry: `{"term":1}`},
60			{name: "omits term", entry: `{"index":1}`},
61		}
62		for _, tc := range cases {
63			t.Run(tc.name, func(t *testing.T) {
64				input := `{"currentTerm":1,"committedIndex":1,
65				  "log":[{"index":1,"term":1,"command":"set a=1"}],
66				  "log":[` + tc.entry + `]}`
67				runReplicateExpectInputError(t, input, "invalid initial state")
68			})
69		}
70	}
71	
72	// 后一份 log 更短时只保留它实际给出的元素，前一份多出的尾部必须丢弃，
73	// 且保留下来的元素不借用旧内容。
74	func TestCLIDuplicateLogShorterArrayDropsOldTail(t *testing.T) {
75		input := `{"currentTerm":2,
76		  "log":[{"index":1,"term":1,"command":"a"},{"index":2,"term":2,"command":"b"}],
77		  "log":[{"index":1,"term":1,"command":"Z"}]}`
78		out := runReplicateJSON(t, input)
79		want := []mevwatch.LogEntry{{Index: 1, Term: 1, Command: "Z"}}
80		if len(out.FinalLog) != len(want) || out.FinalLog[0] != want[0] {
81			t.Fatalf("final log = %+v, want only the second array's %+v", out.FinalLog, want)
82		}
83	}
84	
85	// 后一份 log 为 null 时与单份 log:null 一致：日志为空。
86	func TestCLIDuplicateLogLaterNullEmptiesLog(t *testing.T) {
87		input := `{"currentTerm":1,
88		  "log":[{"index":1,"term":1,"command":"a"}],"log":null,"requests":[]}`
89		out := runReplicateJSON(t, input)
90		if len(out.FinalLog) != 0 {
