568			out.FinalLog[0] != (mevwatch.LogEntry{Index: 1, Term: 1, Command: "incr count=10"}) ||
569			out.FinalLog[1] != (mevwatch.LogEntry{Index: 2, Term: 2, Command: "incr count=-3"}) {
570			t.Fatalf("final log must drop the old suffix and keep the committed prefix: %+v", out.FinalLog)
571		}
572		if out.FinalAppliedIndex == nil || *out.FinalAppliedIndex != 2 {
573			t.Fatalf("final appliedIndex = %+v, want 2", out.FinalAppliedIndex)
574		}
575		if len(out.FinalKV) != 1 || out.FinalKV["count"] != "7" {
576			t.Fatalf("finalKV = %v, want count=7 (10 on the committed prefix, then -3)", out.FinalKV)
577		}
578		if out.FinalApplyError != nil {
579			t.Fatalf("unexpected final apply error: %+v", out.FinalApplyError)
580		}
581	}
582	
583	// TestCLIApplyKVIncrSameTermConflictRejects 端到端锁定区分情形一：冲突位置的
584	// 索引与任期都与旧条目相同（idx2 仍是任期 1），只是命令变成 incr count=-3。
585	// 整条请求按现有同任期命令冲突拒绝：accepted=false 并给出具体原因，无 conflict
586	// 键；旧后缀不能被提交、新命令不能被应用；日志、计数 "10"、提交与应用位置保持
587	// 原样；较高请求任期 3 仍按现有规则保留。
588	func TestCLIApplyKVIncrSameTermConflictRejects(t *testing.T) {
589		input := incrSuffixReplacementInput(
590			`{"term": 3, "prevLogIndex": 1, "prevLogTerm": 1, "leaderCommit": 3,
591		     "entries": [
592		       {"index": 2, "term": 1, "command": "incr count=-3"},
593		       {"index": 3, "term": 3, "command": "set other=x"}
594		     ]}`)
595		out := runReplicateJSON(t, input)
596		result := out.Results[0]
597		if result.Accepted || result.Reason != mevwatch.ReasonCommandConflictSameTerm {
598			t.Fatalf("expected same-term command conflict rejection, got %+v", result)
599		}
600		if result.Conflict != nil {
601			t.Fatalf("command conflict must not carry a conflict hint: %+v", result.Conflict)
602		}
603		if result.Term != 3 {
604			t.Fatalf("higher request term must survive rejection, term = %d, want 3", result.Term)
605		}
606		if result.CommittedIndex != 1 {
607			t.Fatalf("commit moved on rejection: %d, want 1", result.CommittedIndex)
608		}
609		if result.AppliedIndex == nil || *result.AppliedIndex != 1 || result.ApplyError != nil {
610			t.Fatalf("result apply state = %+v %+v, want appliedIndex 1 and no error",
611				result.AppliedIndex, result.ApplyError)
612		}
613		if len(out.FinalLog) != 3 ||
614			out.FinalLog[0] != (mevwatch.LogEntry{Index: 1, Term: 1, Command: "incr count=10"}) ||
615			out.FinalLog[1] != (mevwatch.LogEntry{Index: 2, Term: 1, Command: "incr count=100"}) ||
616			out.FinalLog[2] != (mevwatch.LogEntry{Index: 3, Term: 1, Command: "incr count=1.5"}) {
617			t.Fatalf("log must be unchanged after the atomic rejection: %+v", out.FinalLog)
618		}
619		if out.FinalTerm != 3 || out.FinalCommittedIndex != 1 {
620			t.Fatalf("unexpected final state: %+v", out)
621		}
622		if out.FinalAppliedIndex == nil || *out.FinalAppliedIndex != 1 {
623			t.Fatalf("final appliedIndex = %+v, want 1", out.FinalAppliedIndex)
624		}
625		if len(out.FinalKV) != 1 || out.FinalKV["count"] != "10" {
626			t.Fatalf("finalKV = %v, want only count=10", out.FinalKV)
627		}
628		if out.FinalApplyError != nil {
629			t.Fatalf("unexpected final apply error: %+v", out.FinalApplyError)
630		}
631	}
632	
633	// TestCLIApplyKVIncrTermConflictBadDeltaApplyError 端到端锁定区分情形二：不同
634	// 任期的替换本身合法（idx2 旧任期 1、新任期 3），但新条目 incr count=x 的增量
635	// 不是整数。复制与提交成功（接受、提交位置到 2、日志完成替换，旧后缀消失），
636	// 只有提交后的应用在正常 JSON 中报告错误：appliedIndex 停在 1，applyError 指向
637	// idx2 并给出具体原因，计数保留 "10"。调用正常完成（退出码 0、stderr 为空）。
638	func TestCLIApplyKVIncrTermConflictBadDeltaApplyError(t *testing.T) {
639		input := incrSuffixReplacementInput(
640			`{"term": 3, "prevLogIndex": 1, "prevLogTerm": 1, "leaderCommit": 2,
641		     "entries": [{"index": 2, "term": 3, "command": "incr count=x"}]}`)
642		out := runReplicateJSON(t, input)
643		result := out.Results[0]
644		if !result.Accepted || result.Reason != mevwatch.ReasonOK {
645			t.Fatalf("replication of the legal replacement must succeed: %+v", result)
646		}
647		if result.Term != 3 || result.CommittedIndex != 2 {
648			t.Fatalf("result state = term %d ci %d, want term 3 ci 2", result.Term, result.CommittedIndex)
649		}
650		if result.AppliedIndex == nil || *result.AppliedIndex != 1 {
651			t.Fatalf("result appliedIndex = %+v, want 1 (stopped before the bad new entry)", result.AppliedIndex)
652		}
653		if result.ApplyError == nil || result.ApplyError.Index != 2 ||
654			result.ApplyError.Reason != mevwatch.ApplyReasonIncrBadDelta {
655			t.Fatalf("result applyError = %+v, want index 2 bad delta", result.ApplyError)
656		}
657		if len(out.FinalLog) != 2 ||
658			out.FinalLog[0] != (mevwatch.LogEntry{Index: 1, Term: 1, Command: "incr count=10"}) ||
659			out.FinalLog[1] != (mevwatch.LogEntry{Index: 2, Term: 3, Command: "incr count=x"}) {
660			t.Fatalf("final log must reflect the successful replacement: %+v", out.FinalLog)
661		}
662		if out.FinalTerm != 3 || out.FinalCommittedIndex != 2 {
663			t.Fatalf("unexpected final state: %+v", out)
664		}
665		if out.FinalAppliedIndex == nil || *out.FinalAppliedIndex != 1 {
666			t.Fatalf("final appliedIndex = %+v, want 1", out.FinalAppliedIndex)
667		}
668		if len(out.FinalKV) != 1 || out.FinalKV["count"] != "10" {
669			t.Fatalf("finalKV = %v, want only count=10 (bad new incr leaves the table unchanged)", out.FinalKV)
670		}
671		if out.FinalApplyError == nil || out.FinalApplyError.Index != 2 ||
672			out.FinalApplyError.Reason != mevwatch.ApplyReasonIncrBadDelta {
673			t.Fatalf("final applyError = %+v, want index 2 bad delta", out.FinalApplyError)
674		}
675	}
676	
677	// TestCLIApplyKVIncrTermConflictDisabledShape 不开启 applyKV 时，不同任期替换
678	// 照常进行，但 incr 只是普通字符串：输出保持现状形状，没有任何应用字段。
679	func TestCLIApplyKVIncrTermConflictDisabledShape(t *testing.T) {
680		input := `{
681	  "currentTerm": 2,
682	  "committedIndex": 1,
683	  "log": [
684	    {"index": 1, "term": 1, "command": "incr count=10"},
685	    {"index": 2, "term": 1, "command": "incr count=100"},
686	    {"index": 3, "term": 1, "command": "incr count=1.5"}
687	  ],
688	  "requests": [
689	    {"term": 2, "prevLogIndex": 1, "prevLogTerm": 1, "leaderCommit": 2,
690	     "entries": [{"index": 2, "term": 2, "command": "incr count=-3"}]}
691	  ]
692	}`
693		var stdout, stderr bytes.Buffer
694		code := runReplicateIO(strings.NewReader(input), &stdout, &stderr)
695		if code != 0 {
696			t.Fatalf("exit code = %d, stderr=%s", code, stderr.String())
697		}
698		var out mevwatch.ReplicateOutput
699		if err := json.Unmarshal(stdout.Bytes(), &out); err != nil {
700			t.Fatalf("stdout is not valid JSON: %v\n%s", err, stdout.String())
701		}
702		if !out.Results[0].Accepted || out.FinalCommittedIndex != 2 || len(out.FinalLog) != 2 {
703			t.Fatalf("replication should succeed without applyKV: %+v", out)
704		}
705		body := stdout.String()
706		for _, field := range []string{"appliedIndex", "applyError", "finalAppliedIndex", "finalKV", "finalApplyError"} {
707			if strings.Contains(body, field) {
708				t.Fatalf("applyKV disabled: output must not contain %q:\n%s", field, body)
709			}
710		}
711		if !strings.Contains(body, "incr count=-3") {
712			t.Fatalf("incr command must be replicated verbatim:\n%s", body)
713		}
714	}
715	
716	// TestCLIApplyKVIncrOverflowStuckThenSuffixReplacement 端到端锁定“应用因 incr
717	// 溢出停住 × 任期冲突替换未提交后缀”相遇时的公开 JSON：
718	//   - 初始任期 1、三条任期 1 的日志、提交位置 2：idx1 set count=最大整数已生效，
719	//     idx2 incr count=1 因 MaxInt64+1 溢出让应用停在 1（错误指向 idx2），idx3
720	//     incr count=-1 尚未提交，不能提前减一消除错误；
721	//   - 请求一（任期 2，前置 idx2/任期 1）用任期 2 的 set count=0 与 incr count=1
722	//     替换旧 idx3 并追加 idx4，leaderCommit=4：合法后缀替换照常接受，任期升到 2、
723	//     提交到 4，最终日志保留两条已提交记录、旧减一命令消失、新后缀完整出现；
724	//     但新命令即使格式正确且已复制、已提交也不生效，计数仍是最大整数，应用位置
725	//     仍为 1，逐条结果与最终结果都保留 idx2 的同一溢出原因；
726	//   - 请求二（任期 3，匹配 idx1）试图以不同任期改写已提交的 idx2：按覆盖已提交
727	//     条目拒绝（无 conflict 键），较高任期 3 保留，日志、提交位置、键值表与首次
728	//     应用错误均不变。两条请求各自保留当时的接受/拒绝结果。
729	func TestCLIApplyKVIncrOverflowStuckThenSuffixReplacement(t *testing.T) {
730		input := `{
731	  "currentTerm": 1,
732	  "committedIndex": 2,
733	  "log": [
734	    {"index": 1, "term": 1, "command": "set count=9223372036854775807"},
735	    {"index": 2, "term": 1, "command": "incr count=1"},
736	    {"index": 3, "term": 1, "command": "incr count=-1"}
737	  ],
738	  "applyKV": true,
739	  "requests": [
740	    {"term": 2, "prevLogIndex": 2, "prevLogTerm": 1, "leaderCommit": 4,
741	     "entries": [
742	       {"index": 3, "term": 2, "command": "set count=0"},
743	       {"index": 4, "term": 2, "command": "incr count=1"}
744	     ]},
745	    {"term": 3, "prevLogIndex": 1, "prevLogTerm": 1, "leaderCommit": 4,
746	     "entries": [
747	       {"index": 2, "term": 3, "command": "set count=0"},
748	       {"index": 3, "term": 3, "command": "set count=1"},
749	       {"index": 4, "term": 3, "command": "incr count=1"}
750	     ]}
751	  ]
752	}`
753		var stdout, stderr bytes.Buffer
754		code := runReplicateIO(strings.NewReader(input), &stdout, &stderr)
755		if code != 0 {
756			t.Fatalf("exit code = %d, stderr=%s", code, stderr.String())
757		}
758		if stderr.Len() != 0 {
759			t.Fatalf("replication verdict (including rejection) is normal output, stderr must be empty, got %q", stderr.String())
760		}
761		var out mevwatch.ReplicateOutput
762		if err := json.Unmarshal(stdout.Bytes(), &out); err != nil {
763			t.Fatalf("stdout is not valid JSON: %v\n%s", err, stdout.String())
764		}
765		if len(out.Results) != 2 {
766			t.Fatalf("expected 2 results in request order, got %+v", out.Results)
767		}
768	
769		// 请求一：合法后缀替换接受；复制推进，但应用停在 idx2 的溢出错误上。
770		first := out.Results[0]
771		if !first.Accepted || first.Reason != mevwatch.ReasonOK {
772			t.Fatalf("legal suffix replacement must be accepted: %+v", first)
773		}
774		if first.Conflict != nil {
775			t.Fatalf("accepted replacement must not carry a conflict hint: %+v", first.Conflict)
776		}
777		if first.Term != 2 || first.CommittedIndex != 4 {
778			t.Fatalf("first result state = term %d ci %d, want term 2 ci 4",
779				first.Term, first.CommittedIndex)
780		}
781		if first.AppliedIndex == nil || *first.AppliedIndex != 1 {
782			t.Fatalf("first result appliedIndex = %+v, want 1 (stuck before the overflow entry)",
783				first.AppliedIndex)
784		}
785		if first.ApplyError == nil || first.ApplyError.Index != 2 ||
786			first.ApplyError.Reason != mevwatch.ApplyReasonIncrOverflow {
787			t.Fatalf("first result applyError = %+v, want index 2 overflow", first.ApplyError)
788		}
789	
790		// 请求二：覆盖已提交的 idx2 被拒；高任期保留，其余（含首次应用错误）不变。
791		second := out.Results[1]
792		if second.Accepted || second.Reason != mevwatch.ReasonWouldOverwriteCommitted {
793			t.Fatalf("overwriting committed idx2 must be rejected, got %+v", second)
794		}
795		if second.Conflict != nil {
796			t.Fatalf("committed-overwrite rejection must not carry a conflict hint: %+v", second.Conflict)
797		}
798		if second.Term != 3 || second.CommittedIndex != 4 {
799			t.Fatalf("second result state = term %d ci %d, want term 3 ci 4",
800				second.Term, second.CommittedIndex)
801		}
802		if second.AppliedIndex == nil || *second.AppliedIndex != 1 {
803			t.Fatalf("second result appliedIndex = %+v, want 1", second.AppliedIndex)
804		}
805		if second.ApplyError == nil || second.ApplyError.Index != 2 ||
806			second.ApplyError.Reason != mevwatch.ApplyReasonIncrOverflow {
807			t.Fatalf("second result applyError = %+v, want the original index 2 overflow error",
808				second.ApplyError)
809		}
810	
811		// 最终状态：任期升到 3；提交位置 4；日志为原两条已提交记录加任期 2 的新后缀，
812		// 旧的 incr count=-1 消失。
813		if out.FinalTerm != 3 || out.FinalCommittedIndex != 4 {
814			t.Fatalf("unexpected final state: term=%d ci=%d", out.FinalTerm, out.FinalCommittedIndex)
815		}
816		wantLog := []mevwatch.LogEntry{
817			{Index: 1, Term: 1, Command: "set count=9223372036854775807"},
818			{Index: 2, Term: 1, Command: "incr count=1"},
819			{Index: 3, Term: 2, Command: "set count=0"},
820			{Index: 4, Term: 2, Command: "incr count=1"},
821		}
822		if len(out.FinalLog) != len(wantLog) {
823			t.Fatalf("final log has %d entries, want %d: %+v", len(out.FinalLog), len(wantLog), out.FinalLog)
824		}
825		for i, want := range wantLog {
826			if out.FinalLog[i] != want {
827				t.Fatalf("final log[%d] = %+v, want %+v (old decrement gone, new suffix intact)",
828					i, out.FinalLog[i], want)
829			}
830		}
831		// 已复制、已提交不等于已生效：计数保留最大整数，set count=0 未写入，应用停住。
832		if out.FinalAppliedIndex == nil || *out.FinalAppliedIndex != 1 {
833			t.Fatalf("finalAppliedIndex = %+v, want 1", out.FinalAppliedIndex)
834		}
835		if len(out.FinalKV) != 1 || out.FinalKV["count"] != "9223372036854775807" {
836			t.Fatalf("finalKV = %v, want only the max int64 string (newly committed suffix not applied)",
837				out.FinalKV)
838		}
839		if out.FinalApplyError == nil || out.FinalApplyError.Index != 2 ||
840			out.FinalApplyError.Reason != mevwatch.ApplyReasonIncrOverflow {
841			t.Fatalf("finalApplyError = %+v, want the original index 2 overflow error",
842				out.FinalApplyError)
843		}
844		// 覆盖已提交条目属于冲突/提交类拒绝，不是前置日志不匹配：输出不含 conflict 键。
845		if strings.Contains(stdout.String(), `"conflict"`) {
846			t.Fatalf("output must not contain a conflict hint:\n%s", stdout.String())
847		}
848	}
849	
850	func TestCLIErrors(t *testing.T) {
851		cases := []string{
852			`not json`,
853			`{"currentTerm": 2, "committedIndex": 9, "log": [], "requests": []}`,
854			`{"currentTerm": 0, "log": [{"index": 1, "term": 2, "command": "a"}]}`,
855		}
856		for _, input := range cases {
857			var stdout, stderr bytes.Buffer
858			code := runReplicateIO(strings.NewReader(input), &stdout, &stderr)
859			if code != 1 {
860				t.Fatalf("input %q: exit code = %d, want 1", input, code)
861			}
862			if stdout.Len() != 0 {
863				t.Fatalf("input %q: unexpected stdout on error: %s", input, stdout.String())
864			}
865			if !strings.Contains(stderr.String(), "replicate:") {
866				t.Fatalf("input %q: error message missing prefix: %s", input, stderr.String())
867			}
868		}
869	}
