1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"strings"
7		"testing"
8	
9		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
10	)
11	
12	// runReplicateRaw 执行一次 replicate，断言正常完成（退出码 0、stderr 为空），
13	// 同时返回解码后的结果与原始输出文本：conflict 键“完全不出现”与“出现但为
14	// null”只能通过原始文本区分。
15	func runReplicateRaw(t *testing.T, input string) (mevwatch.ReplicateOutput, string) {
16		t.Helper()
17		var stdout, stderr bytes.Buffer
18		code := runReplicateIO(strings.NewReader(input), &stdout, &stderr)
19		if code != 0 {
20			t.Fatalf("exit code = %d, stderr=%s", code, stderr.String())
21		}
22		if stderr.Len() != 0 {
23			t.Fatalf("replication rejection is normal output, stderr must be empty, got %q", stderr.String())
24		}
25		var out mevwatch.ReplicateOutput
26		if err := json.Unmarshal(stdout.Bytes(), &out); err != nil {
27			t.Fatalf("stdout is not valid JSON: %v\n%s", err, stdout.String())
28		}
29		return out, stdout.String()
30	}
31	
32	// TestCLIConflictHintTermMismatchApplyKV 端到端锁定前置索引存在但任期不同时的
33	// 拒绝答复（开启 applyKV）：本地四条日志任期依次为 1、2、2、2，已提交到 3
34	// （计数 1+10+100="111"），idx4 的 incr count=1000 是未提交尾部。请求把 idx4
35	// 作为前置日志却声称其任期为 3，并携带更高任期 5：
36	//   - accepted=false，reason 为既有的前置日志不匹配原因；
37	//   - conflict 的 term 是 idx4 的本地任期 2，index 是该任期在完整本地日志中的
38	//     首次出现位置 2——它落在已提交前缀内，不能因开启键值应用而改成提交位置之后；
39	//   - 任期提升保留（结果与最终任期都是 5），但日志、提交位置 3、已应用位置 3
40	//     都保持请求前的值，未提交尾部的增量不改变键值表（计数仍是 "111"），被拒绝
41	//     的命令不出现在输出中。
42	func TestCLIConflictHintTermMismatchApplyKV(t *testing.T) {
43		input := `{
44		  "currentTerm": 2,
45		  "committedIndex": 3,
46		  "log": [
47		    {"index": 1, "term": 1, "command": "set count=1"},
48		    {"index": 2, "term": 2, "command": "incr count=10"},
49		    {"index": 3, "term": 2, "command": "incr count=100"},
50		    {"index": 4, "term": 2, "command": "incr count=1000"}
51		  ],
52		  "applyKV": true,
53		  "requests": [
54		    {"term": 5, "prevLogIndex": 4, "prevLogTerm": 3, "leaderCommit": 4,
55		     "entries": [{"index": 5, "term": 5, "command": "set hacked=yes"}]}
56		  ]
57		}`
58		out, body := runReplicateRaw(t, input)
59		if len(out.Results) != 1 {
60			t.Fatalf("expected 1 result, got %+v", out.Results)
61		}
62		result := out.Results[0]
63		if result.Accepted || result.Reason != mevwatch.ReasonPrevLogMismatch {
64			t.Fatalf("expected prev-log-mismatch rejection, got %+v", result)
65		}
66		if result.Conflict == nil ||
67			*result.Conflict != (mevwatch.ConflictHint{Index: 2, Term: 2}) {
68			t.Fatalf("conflict = %+v, want {index 2, term 2}: first occurrence of the local term, "+
69				"even though it lies inside the committed prefix", result.Conflict)
70		}
71		if result.Term != 5 {
72			t.Fatalf("higher request term must survive the rejection, term = %d, want 5", result.Term)
73		}
74		if result.CommittedIndex != 3 {
75			t.Fatalf("rejection must not move committedIndex, got %d, want 3", result.CommittedIndex)
76		}
77		if result.AppliedIndex == nil || *result.AppliedIndex != 3 || result.ApplyError != nil {
78			t.Fatalf("result apply state = %+v %+v, want appliedIndex 3 and no error",
79				result.AppliedIndex, result.ApplyError)
80		}
81		if out.FinalTerm != 5 || out.FinalCommittedIndex != 3 {
82			t.Fatalf("unexpected final state: term=%d ci=%d, want term 5 ci 3",
83				out.FinalTerm, out.FinalCommittedIndex)
84		}
85		wantLog := []mevwatch.LogEntry{
86			{Index: 1, Term: 1, Command: "set count=1"},
87			{Index: 2, Term: 2, Command: "incr count=10"},
88			{Index: 3, Term: 2, Command: "incr count=100"},
89			{Index: 4, Term: 2, Command: "incr count=1000"},
90		}
91		if len(out.FinalLog) != len(wantLog) {
92			t.Fatalf("final log has %d entries, want %d (unchanged): %+v",
93				len(out.FinalLog), len(wantLog), out.FinalLog)
94		}
95		for i, want := range wantLog {
96			if out.FinalLog[i] != want {
97				t.Fatalf("final log[%d] = %+v, want %+v (rejection must not touch the log)",
98					i, out.FinalLog[i], want)
99			}
100		}
101		if out.FinalAppliedIndex == nil || *out.FinalAppliedIndex != 3 {
102			t.Fatalf("finalAppliedIndex = %+v, want 3", out.FinalAppliedIndex)
103		}
104		if len(out.FinalKV) != 1 || out.FinalKV["count"] != "111" {
105			t.Fatalf("finalKV = %v, want only count=111 (uncommitted incr count=1000 must not apply)",
106				out.FinalKV)
107		}
108		if out.FinalApplyError != nil {
109			t.Fatalf("unexpected final apply error: %+v", out.FinalApplyError)
110		}
111		if strings.Contains(body, "hacked") {
112			t.Fatalf("the rejected entry's command must not appear in the output:\n%s", body)
113		}
114	}
115	
116	// TestCLIConflictHintBeyondLogEndApplyKV 端到端锁定前置索引越过本地日志末尾时
117	// 的建议：指向末尾加一、term 明确输出为 0。这是正常的单条复制拒绝，整次调用
118	// 仍成功输出完整 JSON（退出码 0、stderr 为空），提交位置与键值表保持原样。
119	func TestCLIConflictHintBeyondLogEndApplyKV(t *testing.T) {
120		input := `{
121		  "currentTerm": 1,
122		  "committedIndex": 2,
123		  "log": [
124		    {"index": 1, "term": 1, "command": "set a=1"},
125		    {"index": 2, "term": 1, "command": "set b=2"}
126		  ],
127		  "applyKV": true,
128		  "requests": [
129		    {"term": 1, "prevLogIndex": 5, "prevLogTerm": 1, "entries": [], "leaderCommit": 2}
130		  ]
131		}`
132		out, body := runReplicateRaw(t, input)
133		if len(out.Results) != 1 {
134			t.Fatalf("expected 1 result, got %+v", out.Results)
135		}
136		result := out.Results[0]
137		if result.Accepted || result.Reason != mevwatch.ReasonPrevLogMismatch {
138			t.Fatalf("expected prev-log-mismatch rejection, got %+v", result)
139		}
140		if result.Conflict == nil ||
141			*result.Conflict != (mevwatch.ConflictHint{Index: 3, Term: 0}) {
142			t.Fatalf("conflict = %+v, want {index 3, term 0} (last local index plus one)",
143				result.Conflict)
144		}
145		if result.Term != 1 || result.CommittedIndex != 2 {
